// #e4e484a00eca59f5dd60d15f (#60d15f) — /admin/support: после пройденной кандидатом тех. проверки колонка «קישור»
// = «בדיקה טכנית עברה · בשלב התרגול» (не «בדיקה טכנית החלה»), «עדכון אחרון» обновлён.
// Кейс SUP-005 · spec: specs/support.md (3.1). Три роли: business (ссылка), кандидат (Chrome с фальшивым микрофоном), admin.
// Данные: кандидат «QA-AUTO-60d15f-<stamp>» (link_only, ничего не отправляется), не удаляется (удаления кандидатов нет).
// OpenAI не тратится: кандидат останавливается на «פרטי לקוח לתרגול», звонок не начинается.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { Candidate, createCandidateLink, launchCandidate, goToPractice } from '../candidate-call/support';

let cand: Candidate | undefined;

test.afterAll(async () => {
  await cand?.browser.close();
});

/** Время в Asia/Jerusalem как число YYYYMMDDHHMM (точность — минута, как в колонке). */
function jerusalemMinute(d: Date): number {
  const p = Object.fromEntries(
    new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jerusalem', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false })
      .formatToParts(d)
      .map((x) => [x.type, x.value]),
  );
  return Number(`${p.year}${p.month}${p.day}${p.hour === '24' ? '00' : p.hour}${p.minute}`);
}

/** «21.10.26, 18:02» → 202610211802. */
function parseShown(s: string): number {
  const m = s.match(/(\d{2})\.(\d{2})\.(\d{2}),\s*(\d{2}):(\d{2})/);
  expect(m, `формат «עדכון אחרון»: ${s}`).toBeTruthy();
  return Number(`20${m![3]}${m![2]}${m![1]}${m![4]}${m![5]}`);
}

async function supportRow(admin: Page, name: string) {
  await admin.goto('/admin/support');
  await expect(admin.getByRole('heading', { level: 1, name: 'תמיכה ותפעול' })).toBeVisible();
  const row = admin.getByRole('row').filter({ hasText: name });
  await expect(row, `нет строки «${name}» в /admin/support`).toHaveCount(1);
  return {
    link: row.locator('td[data-label="קישור"]'),
    updated: row.locator('td[data-label="עדכון אחרון"]'),
  };
}

test.describe('Поддержка — статус ссылки после тех. проверки (#e4e484a00eca59f5dd60d15f)', () => {
  test('после пройденной тех. проверки «קישור» = «בדיקה טכנית עברה · בשלב התרגול», «עדכון אחרון» обновлён @desktop @data #e4e484a00eca59f5dd60d15f', async ({ asUser }) => {
    test.setTimeout(4 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-60d15f-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}», ссылка ${link} (после тех. проверки), не удаляется` });

    const admin = await asUser('admin');
    const before = await supportRow(admin, name);
    await expect(before.link).not.toContainText('בדיקה טכנית עברה');

    const startedAt = jerusalemMinute(new Date());
    cand = await launchCandidate({ width: 1440, height: 900 });
    await goToPractice(cand.page, link); // вступление → согласие → тех. проверка «כן, שומעים טוב» → «להמשיך לתרגול»

    // Источник: «מה רצוי» / AC #60d15f.
    await expect(async () => {
      const after = await supportRow(admin, name);
      await expect(after.link).toContainText('בדיקה טכנית עברה', { timeout: 2_000 });
    }).toPass({ timeout: 60_000 });
    const after = await supportRow(admin, name);
    await expect(after.link).not.toContainText('בדיקה טכנית החלה');
    await expect(after.link.getByText('בשלב התרגול', { exact: true })).toBeVisible();
    const shown = (await after.updated.innerText()).trim();
    expect(parseShown(shown), `«עדכון אחרון» ${shown} не раньше начала тех. проверки`).toBeGreaterThanOrEqual(startedAt);
  });
});
